import React, { useState, useEffect } from 'react';
import './Achat.css';

function Achat({ allerVers, utilisateur, musiqueId }) {
  const [musique, setMusique] = useState(null);
  const [operateur, setOperateur] = useState('mtn');
  const [numero, setNumero] = useState('');
  const [etape, setEtape] = useState('paiement');
  const [chargement, setChargement] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetch('/api/musiques')
      .then(res => res.json())
      .then(data => {
        const m = data.musiques.find(m => m.id === parseInt(musiqueId));
        setMusique(m);

        // Pré-sélectionner l'opérateur selon les numéros de l'artiste
        if (m) {
          if (m.numero_mtn) setOperateur('mtn');
          else if (m.numero_airtel) setOperateur('airtel');
        }
      });

    // Pré-remplir le numéro de l'acheteur
    if (utilisateur) {
      setNumero(utilisateur.numero_paiement_prefere || utilisateur.telephone || '');
    }
  }, [musiqueId, utilisateur]);

  const accepteMtn = musique?.numero_mtn ? true : false;
  const accepteAirtel = musique?.numero_airtel ? true : false;

  const handlePaiement = async () => {
    if (!utilisateur) {
      allerVers('login');
      return;
    }

    if (!numero) {
      setMessage('❌ Entrez votre numéro Mobile Money !');
      return;
    }

    const numeroPropre = numero.replace(/\s/g, '').replace('+242', '');

    if (operateur === 'mtn' && !numeroPropre.startsWith('06')) {
      setMessage('❌ Un numéro MTN doit commencer par 06 !');
      return;
    }

    if (operateur === 'airtel' && !numeroPropre.startsWith('05') && !numeroPropre.startsWith('04')) {
      setMessage('❌ Un numéro Airtel doit commencer par 05 ou 04 !');
      return;
    }

    setChargement(true);
    setMessage('');

    try {
      const reponse = await fetch('/api/achats', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          acheteur_id: utilisateur.id,
          musique_id: parseInt(musiqueId),
          operateur,
          numero_paiement: numero
        })
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        // Sauvegarder le numéro préféré de l'acheteur
        await fetch('/api/auth/sauvegarder-numero', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            utilisateur_id: utilisateur.id,
            numero_paiement_prefere: numero
          })
        });
        setEtape('succes');
      } else {
        setMessage('❌ ' + donnees.message);
      }

    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  if (!musique) return <div className="achat-page"><div className="chargement">Chargement...</div></div>;

  if (etape === 'succes') {
    return (
      <div className="achat-page">
        <div className="achat-box">
          <div className="succes-icone">🎉</div>
          <h2 className="succes-titre">Paiement réussi !</h2>
          <p className="succes-texte">
            <strong>{musique.titre}</strong> a été ajouté à votre bibliothèque.
          </p>
          <p className="succes-detail">
            {musique.prix} FCFA débités sur votre compte {operateur.toUpperCase()} (+242 {numero})
          </p>
          <button className="btn-bibliotheque" onClick={() => allerVers('bibliotheque')}>
            🎵 Voir ma bibliothèque
          </button>
          <button className="btn-retour-catalogue" onClick={() => allerVers('catalogue')}>
            ← Retour au catalogue
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="achat-page">
      <div className="achat-box">
        <h1 className="achat-logo">🎵 Varim Music</h1>
        <h2 className="achat-titre">Finaliser l'achat</h2>

        <div className="achat-recap">
          {musique.pochette_url && (
            <img src={musique.pochette_url} alt={musique.titre} className="achat-pochette" />
          )}
          <div className="achat-info">
            <h3>{musique.titre}</h3>
            <p>🎤 {musique.nom_artiste}</p>
            <p className="achat-type">{musique.type === 'album' ? '💿 Album' : '🎵 Single'}</p>
            <p className="achat-prix">{musique.prix} FCFA</p>
          </div>
        </div>

        {message && <div className="achat-message">{message}</div>}

        <div className="achat-champ">
          <label>Choisir l'opérateur</label>
          <div className="operateurs">
            <div
              className={`operateur-carte ${operateur === 'mtn' ? 'active' : ''} ${!accepteMtn ? 'desactive' : ''}`}
              onClick={() => accepteMtn && setOperateur('mtn')}
            >
              <span className="operateur-logo mtn">MTN</span>
              <span>Mobile Money</span>
              {!accepteMtn && (
                <small style={{color:'#ff4444', fontSize:'11px'}}>
                  ❌ Non disponible
                </small>
              )}
            </div>
            <div
              className={`operateur-carte ${operateur === 'airtel' ? 'active' : ''} ${!accepteAirtel ? 'desactive' : ''}`}
              onClick={() => accepteAirtel && setOperateur('airtel')}
            >
              <span className="operateur-logo airtel">Airtel</span>
              <span>Money</span>
              {!accepteAirtel && (
                <small style={{color:'#ff4444', fontSize:'11px'}}>
                  ❌ Non disponible
                </small>
              )}
            </div>
          </div>
          {!accepteMtn && !accepteAirtel && (
            <p style={{color:'#ff4444', fontSize:'13px', marginTop:'10px'}}>
              ❌ Cet artiste n'a pas encore configuré ses moyens de paiement.
            </p>
          )}
        </div>

        <div className="achat-champ">
          <label>
            Votre numéro {operateur === 'mtn' ? 'MTN' : 'Airtel'} (+242)
          </label>
          <div style={{display:'flex', gap:'10px', alignItems:'center'}}>
            <span style={{
              background:'#1e2a4a', color:'#4f9cf9',
              padding:'12px 10px', borderRadius:'8px',
              fontSize:'14px', fontWeight:'bold',
              whiteSpace:'nowrap'
            }}>+242</span>
            <input
              type="tel"
              placeholder={operateur === 'mtn' ? '06XXXXXXX' : '05XXXXXXX'}
              value={numero}
              onChange={(e) => setNumero(e.target.value)}
              style={{flex:1}}
            />
          </div>
          <small style={{color:'#a0aec0', fontSize:'12px', marginTop:'5px', display:'block'}}>
            💡 Numéro pré-rempli depuis votre compte. Modifiez si nécessaire.
          </small>
        </div>

        <div className="achat-total">
          <span>Total à payer</span>
          <span className="total-prix">{musique.prix} FCFA</span>
        </div>

        {!utilisateur && (
          <p className="achat-connexion">
            ⚠️ <a href="#" onClick={() => allerVers('login')}>Connectez-vous</a> pour acheter
          </p>
        )}

        <button
          className="achat-btn"
          onClick={handlePaiement}
          disabled={chargement || (!accepteMtn && !accepteAirtel)}
        >
          {chargement ? 'Traitement en cours...' : `Payer ${musique.prix} FCFA`}
        </button>

        <button className="btn-annuler" onClick={() => allerVers('catalogue')}>
          Annuler
        </button>
      </div>
    </div>
  );
}

export default Achat;
